public class HelloWorld {                              // Defines a class named HelloWorld every Java program needs at least one class
    public static void main(String[] args) {            // The entry point this is the first method Java runs when the program starts
        System.out.println("Hello, Java 8!");            // Prints text to the console, followed by a new line
    }                                                     // Closes the main method
}                                                         // Closes the class